#!/usr/bin/env bash
# ============================================================
# NAFI Frontend — Step 8 Scaffolding Script (no icons)
# Turns apps/web into an offline-first PWA:
#   - vite-plugin-pwa with Workbox
#   - IndexedDB offline store (contracts, inputs, escrows, queue)
#   - Mutation queue with exponential backoff sync engine
#   - Background Sync + push notifications
#   - OfflineBanner, SyncStatus, InstallPrompt
#   - USSD simulator (admin)
#   - useOfflineMutation + useOfflineContracts
#
# NOTE: PNG icons are NOT generated by this script.
#       Drop them into apps/web/public/pwa/ before shipping:
#         - icon-192.png
#         - icon-512.png
#         - icon-512-maskable.png
# ============================================================
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

echo "▶ NAFI Step 8 scaffolding → $SCRIPT_DIR"

mkfile() {
  local path="$1"
  mkdir -p "$(dirname "$path")"
  cat > "$path"
  echo "  ✓ $path"
}

APP="apps/web"
mkdir -p "$APP/src/offline"
mkdir -p "$APP/public/pwa"
mkdir -p "$APP/src/features/farmer/hooks"
mkdir -p "$APP/src/features/admin/pages"

