            <ol className="flex flex-col gap-1.5 text-sm text-neutral-700">
              {stack.map((s, i) => (
                <li key={`${s}-${i}`} className="flex items-center gap-2">
                  <span className="text-neutral-400">{i + 1}.</span>
                  <span className="font-mono">{s}</span>
                </li>
              ))}
            </ol>

            <div className="mt-4">
              <Input
                placeholder="Type a USSD string e.g. *804#"
                value={input}
                onChange={(e) => setInput(e.target.value)}
              />
            </div>
          </CardBody>
        </Card>
      </div>
    </div>
  );
}
EOF

# ============================================================
# WIRE OfflineProvider into AppProviders
# ============================================================

mkfile "$APP/src/app/providers/AppProviders.tsx" <<'EOF'
import { QueryClientProvider } from '@tanstack/react-query';
import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
import { HelmetProvider } from 'react-helmet-async';
import type { ReactNode } from 'react';
import { I18nextProvider } from 'react-i18next';

import { ToastProvider } from '@/components/ToastProvider';
import i18n from '@/i18n';
import { OfflineProvider } from '@/offline/OfflineProvider';

import { AuthProvider } from '../../auth/AuthProvider';
import { queryClient } from '../queryClient';

export function AppProviders({ children }: { children: ReactNode }) {
  return (
    <HelmetProvider>
      <I18nextProvider i18n={i18n}>
        <QueryClientProvider client={queryClient}>
          <AuthProvider>
            <OfflineProvider>
              <ToastProvider>{children}</ToastProvider>
            </OfflineProvider>
          </AuthProvider>
          {import.meta.env.VITE_ENABLE_QUERY_DEVTOOLS === 'true' && (
            <ReactQueryDevtools initialIsOpen={false} position="bottom" />
          )}
        </QueryClientProvider>
      </I18nextProvider>
    </HelmetProvider>
  );
}
EOF

# ============================================================
# WIRE OfflineBanner + InstallPrompt into DashboardLayout
# ============================================================

# Read the existing file, then rewrite with the additions
if [ -f "$APP/src/layouts/DashboardLayout.tsx" ]; then
  # Insert imports
  sed -i.bak "s|^import { useAuth } from '@/auth/useAuth';$|import { useAuth } from '@/auth/useAuth';\nimport { InstallPrompt } from '@/components/InstallPrompt';\nimport { OfflineBanner } from '@/components/OfflineBanner';|" "$APP/src/layouts/DashboardLayout.tsx" 2>/dev/null || {
    awk '
      /^import \{ useAuth \} from/ {
        print
        print "import { InstallPrompt } from '\''@/components/InstallPrompt'\'';"
        print "import { OfflineBanner } from '\''@/components/OfflineBanner'\'';"
        next
      }
      { print }
    ' "$APP/src/layouts/DashboardLayout.tsx" > "$APP/src/layouts/DashboardLayout.tsx.tmp"
    mv "$APP/src/layouts/DashboardLayout.tsx.tmp" "$APP/src/layouts/DashboardLayout.tsx"
  }
  rm -f "$APP/src/layouts/DashboardLayout.tsx.bak"

  # Insert <OfflineBanner /> after <div className="flex flex-1 flex-col">
  awk '
    /<div className="flex flex-1 flex-col">/ {
      print
      print "        <OfflineBanner />"
      next
    }
    { print }
  ' "$APP/src/layouts/DashboardLayout.tsx" > "$APP/src/layouts/DashboardLayout.tsx.tmp"
  mv "$APP/src/layouts/DashboardLayout.tsx.tmp" "$APP/src/layouts/DashboardLayout.tsx"

  # Insert InstallPrompt before the closing </div> of the outer container
  awk '
    /^      <\/div>$/ {
      print
      print "      {user.role === '\''COMMERCIAL_FARMER'\'' && <InstallPrompt />}"
      next
    }
    { print }
  ' "$APP/src/layouts/DashboardLayout.tsx" > "$APP/src/layouts/DashboardLayout.tsx.tmp"
  mv "$APP/src/layouts/DashboardLayout.tsx.tmp" "$APP/src/layouts/DashboardLayout.tsx"

  echo "  ✓ $APP/src/layouts/DashboardLayout.tsx (patched: OfflineBanner + InstallPrompt)"
fi

# ============================================================
# ROUTER — add USSD simulator route under admin
# ============================================================

# Patch the router to add the USSD route under admin
if [ -f "$APP/src/app/router.tsx" ]; then
  # Add import
  awk '
    /^import \{ AdminAuditPage \} from/ {
      print
      print "import { UssdSimulatorPage } from '\''@/features/admin/pages/UssdSimulatorPage'\'';"
      next
    }
    { print }
  ' "$APP/src/app/router.tsx" > "$APP/src/app/router.tsx.tmp"
  mv "$APP/src/app/router.tsx.tmp" "$APP/src/app/router.tsx"

  # Add route after admin/health
  awk '
    /path: '\''\/admin\/health'\'', element: <AdminHealthPage \/> \}/ {
      print
      print "              { path: '\''/admin/tools/ussd'\'', element: <UssdSimulatorPage /> },"
      next
    }
    { print }
  ' "$APP/src/app/router.tsx" > "$APP/src/app/router.tsx.tmp"
  mv "$APP/src/app/router.tsx.tmp" "$APP/src/app/router.tsx"

  echo "  ✓ $APP/src/app/router.tsx (patched: USSD simulator route)"
fi

